"use strict";

/*
 * cnotes.h documentation viewer.
 * Loads doc.json (generated by `./nob doc`) and renders a searchable API reference.
 */
(function () {
    const DATA_URL = "doc.json";

    // How each tag kind from nob.c is displayed.
    // "field" tags go into the Returns/Outputs table, everything else becomes a callout.
    const TAGS = {
        PARAM:     { label: "Param",     kind: "field" },
        RETURNS:   { label: "Returns",   kind: "field" },
        OUTPUTS:   { label: "Outputs",   kind: "field" },
        SINCE:     { label: "Since",     kind: "field" },
        NOTE:      { label: "Note",      kind: "callout", tone: "note" },
        AI:        { label: "AI",        kind: "callout", tone: "note" },
        IMPORTANT: { label: "Important", kind: "callout", tone: "important" },
        TODO:      { label: "Todo",      kind: "callout", tone: "todo" },
        FIXME:     { label: "Fixme",     kind: "callout", tone: "todo" },
        LEAK:      { label: "Leak",      kind: "callout", tone: "warn" },
        TEMPORARY: { label: "Temporary", kind: "callout", tone: "warn" },
    };
    const FIELD_ORDER = ["PARAM", "RETURNS", "OUTPUTS", "SINCE"];

    const C_KEYWORDS = new Set([
        "const", "volatile", "restrict", "static", "inline", "extern",
        "struct", "union", "enum", "unsigned", "signed", "typedef", "sizeof",
        "if", "else", "for", "while", "do", "switch", "case", "default",
        "break", "continue", "return", "goto",
    ]);
    const C_TYPES = new Set([
        "void", "char", "short", "int", "long", "float", "double", "bool", "_Bool",
        "size_t", "ssize_t", "ptrdiff_t", "intptr_t", "uintptr_t", "va_list", "FILE",
    ]);

    // Signatures longer than this get one parameter per line.
    const WRAP_SIGNATURE_AT = 80;

    const dom = {
        search:  document.getElementById("search"),
        clear:   document.getElementById("search-clear"),
        count:   document.getElementById("result-count"),
        nav:     document.getElementById("nav"),
        entries: document.getElementById("entries"),
        status:  document.getElementById("status"),
        empty:   document.getElementById("empty"),
    };

    const state = {
        entries: [],          // All entries in header order.
        modules: [],          // { name, entries, heading, navGroup, navCount }
        byId:    new Map(),   // Element id -> entry.
        tokens:  [],          // Current lowercase search tokens.
        visible: [],          // Entries currently shown.
    };


    /* ---------- Small helpers ---------- */

    const HTML_ESCAPES = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" };

    function escapeHtml(text) {
        return String(text).replace(/[&<>"']/g, (c) => HTML_ESCAPES[c]);
    }

    function make(tag, className, html) {
        const node = document.createElement(tag);
        if (className) node.className = className;
        if (html !== undefined) node.innerHTML = html;
        return node;
    }

    function isTypingTarget(target) {
        return target instanceof HTMLElement &&
            (target.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(target.tagName));
    }


    /* ---------- Data ---------- */

    function asString(value) {
        return typeof value === "string" ? value : "";
    }

    // Turns raw JSON into a well-formed entry, or null if it is unusable.
    function normalizeEntry(raw, index) {
        if (!raw || typeof raw !== "object") return null;

        const symbol = asString(raw.symbol).trim();
        if (!symbol) return null;

        const tags = (Array.isArray(raw.tags) ? raw.tags : [])
            .filter((tag) => tag && typeof tag === "object")
            .map((tag) => ({
                kind: asString(tag.kind).toUpperCase() || "NOTE",
                text: asString(tag.text).trim(),
            }))
            .filter((tag) => tag.text);

        const entry = {
            index,
            symbol,
            name:        symbol.replace(/^cn_/, ""),
            decl:        asString(raw.decl).trim(),
            summary:     asString(raw.summary).trim(),
            description: asString(raw.description).trim(),
            tags,
        };

        entry.module = entry.name.split("_")[0] || "misc";
        entry.haystack = {
            symbol:  entry.symbol.toLowerCase(),
            name:    entry.name.toLowerCase(),
            decl:    entry.decl.toLowerCase(),
            summary: entry.summary.toLowerCase(),
            rest:    (entry.description + "\n" + tags.map((t) => t.text).join("\n")).toLowerCase(),
        };
        return entry;
    }

    function loadEntries(data) {
        if (!Array.isArray(data)) throw new Error("doc.json must contain a JSON array of entries.");

        const usedIds = new Set();
        for (const raw of data) {
            const entry = normalizeEntry(raw, state.entries.length);
            if (!entry) continue;

            // Ids must be unique even if a symbol is documented twice.
            let id = entry.symbol;
            for (let n = 2; usedIds.has(id); n++) id = `${entry.symbol}-${n}`;
            usedIds.add(id);
            entry.id = id;

            state.entries.push(entry);
            if (!state.byId.has(id)) state.byId.set(id, entry);
        }

        // Group by module (first word after cn_), keeping header order.
        // Single-entry modules are collected into "misc" to keep the sidebar tidy.
        const sizes = new Map();
        for (const e of state.entries) sizes.set(e.module, (sizes.get(e.module) || 0) + 1);

        const byModule = new Map();
        for (const e of state.entries) {
            if (sizes.get(e.module) < 2) e.module = "misc";
            if (!byModule.has(e.module)) byModule.set(e.module, { name: e.module, entries: [] });
            byModule.get(e.module).entries.push(e);
        }

        const misc = byModule.get("misc");
        byModule.delete("misc");
        state.modules = [...byModule.values()];
        if (misc) state.modules.push(misc);
    }


    /* ---------- Rendering: text ---------- */

    // Wraps every occurrence of the search tokens in <mark>. Returns safe HTML.
    function highlight(text, tokens) {
        if (!text || tokens.length === 0) return escapeHtml(text);

        const lower = text.toLowerCase();
        const ranges = [];
        for (const token of tokens) {
            for (let i = lower.indexOf(token); i !== -1; i = lower.indexOf(token, i + token.length)) {
                ranges.push([i, i + token.length]);
            }
        }
        if (ranges.length === 0) return escapeHtml(text);

        ranges.sort((a, b) => a[0] - b[0]);
        let html = "";
        let cursor = 0;
        for (const [start, end] of ranges) {
            if (end <= cursor) continue;
            const from = Math.max(start, cursor);
            html += escapeHtml(text.slice(cursor, from));
            html += `<mark>${escapeHtml(text.slice(from, end))}</mark>`;
            cursor = end;
        }
        return html + escapeHtml(text.slice(cursor));
    }

    // Wraps search matches inside every text node of an already rendered element.
    function markTokens(root, tokens) {
        const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
        const nodes = [];
        while (walker.nextNode()) nodes.push(walker.currentNode);

        for (const node of nodes) {
            const html = highlight(node.nodeValue, tokens);
            if (!html.includes("<mark>")) continue;
            const template = document.createElement("template");
            template.innerHTML = html;
            node.replaceWith(template.content);
        }
    }

    // Entry referenced by `name` or `name()`, null if it is not documented.
    function lookupRef(code) {
        return state.byId.get(code.trim().replace(/\(\s*\)$/, "")) || null;
    }

    // Inline text: `code` links to the entry it names, otherwise it is shown as highlighted code.
    // ```code``` on a single line counts as inline code too.
    function renderInline(text) {
        return text.split(/(```[^\n]+?```|`[^`\n]+`)/).map((part) => {
            if (part.length > 2 && part.startsWith("`") && part.endsWith("`")) {
                const ticks = part.startsWith("```") && part.length > 6 ? 3 : 1;
                const code = part.slice(ticks, -ticks);
                const target = lookupRef(code);
                if (target) return `<a class="xref" href="#${escapeHtml(target.id)}"><code>${escapeHtml(code)}</code></a>`;
                return `<code class="inline-code">${highlightC(code)}</code>`;
            }
            return escapeHtml(part);
        }).join("");
    }

    // Removes indentation common to all non-blank lines.
    function dedent(code) {
        const lines = code.split("\n");
        const indents = lines.filter((l) => l.trim()).map((l) => l.match(/^[ \t]*/)[0].length);
        const cut = indents.length ? Math.min(...indents) : 0;
        return lines.map((l) => l.slice(cut)).join("\n");
    }

    // Content of ```lang ... ```. Only "c" gets syntax colors, anything else (grammar rules, output) stays plain.
    function renderCodeBlock(raw) {
        let lang = "";
        let code = raw;
        const header = /^[ \t]*([A-Za-z0-9_+-]+)[ \t]*\n/.exec(raw);
        if (header) {
            lang = header[1].toLowerCase();
            code = raw.slice(header[0].length);
        }

        code = dedent(code.replace(/^[ \t]*\n/, "")).trimEnd();
        if (!code) return "";

        const body = lang === "c" ? highlightC(code) : escapeHtml(code);
        return `<pre class="code-block"><code>${body}</code></pre>`;
    }

    // Joins wrapped lines of a paragraph back into one line.
    function unwrap(text) {
        return text.split("\n").map((line) => line.trim()).filter(Boolean).join(" ");
    }

    function renderParagraphs(text) {
        return text.split(/\n[ \t]*\n/)
            .map(unwrap)
            .filter(Boolean)
            .map((paragraph) => `<p>${renderInline(paragraph)}</p>`)
            .join("");
    }

    // Same rule as the parser in nob.c: a line starting with ``` opens or closes a fence,
    // unless it closes on the same line too (```one-liner```), which is inline code.
    function isFenceLine(line) {
        const trimmed = line.trim();
        return trimmed.startsWith("```") && !trimmed.slice(3).includes("```");
    }

    // Block text, markdown style: ``` fences become code blocks kept verbatim,
    // the rest is split into paragraphs on blank lines, single "\n" is just a wrapped line.
    // An unclosed fence runs to the end of the text.
    function renderBlocks(text) {
        let html = "";
        let prose = [];
        let code = null; // Lines of the open fence, including its "```lang" header.

        for (const line of text.split("\n")) {
            if (code === null) {
                if (isFenceLine(line)) {
                    html += renderParagraphs(prose.join("\n"));
                    prose = [];
                    code = [line.trim().slice(3)];
                } else {
                    prose.push(line);
                }
            } else if (isFenceLine(line)) {
                html += renderCodeBlock(code.join("\n"));
                code = null;
            } else {
                code.push(line);
            }
        }

        if (code !== null) html += renderCodeBlock(code.join("\n"));
        return html + renderParagraphs(prose.join("\n"));
    }


    /* ---------- Rendering: signatures ---------- */

    function highlightC(code, symbol) {
        const tokenRe = /([A-Za-z_]\w*)|(\s+)|([^\sA-Za-z_]+)/g;
        let html = "";
        let match;
        while ((match = tokenRe.exec(code)) !== null) {
            const [token, ident, space] = match;
            if (space) {
                html += space;
            } else if (ident) {
                if (ident !== symbol && state.byId.has(ident)) {
                    html += `<a class="xref tok-fn" href="#${escapeHtml(ident)}">${escapeHtml(token)}</a>`;
                    continue;
                }
                let cls = "tok-param";
                if (ident === symbol)                                   cls = "tok-fn";
                else if (C_KEYWORDS.has(ident))                         cls = "tok-kw";
                else if (C_TYPES.has(ident) || /^[A-Z]/.test(ident) || /_t$/.test(ident)) cls = "tok-type";
                html += `<span class="${cls}">${escapeHtml(token)}</span>`;
            } else {
                html += `<span class="tok-punct">${escapeHtml(token)}</span>`;
            }
        }
        return html;
    }

    // Splits "a, b (*f)(int, int), c" on top-level commas only.
    function splitParams(params) {
        const parts = [];
        let depth = 0;
        let current = "";
        for (const ch of params) {
            if (ch === "(" || ch === "[") depth++;
            if (ch === ")" || ch === "]") depth--;
            if (ch === "," && depth === 0) {
                parts.push(current.trim());
                current = "";
            } else {
                current += ch;
            }
        }
        if (current.trim()) parts.push(current.trim());
        return parts;
    }

    // Puts one parameter per line for long function signatures.
    function formatSignature(decl, symbol) {
        if (decl.length <= WRAP_SIGNATURE_AT) return decl;

        const nameAt = decl.indexOf(symbol);
        const open = nameAt === -1 ? -1 : decl.indexOf("(", nameAt + symbol.length);
        const close = decl.lastIndexOf(")");
        if (open === -1 || close < open) return decl;

        const params = splitParams(decl.slice(open + 1, close));
        if (params.length < 2) return decl;

        return decl.slice(0, open + 1) + "\n" +
            params.map((p) => "    " + p).join(",\n") + "\n" +
            decl.slice(close);
    }


    /* ---------- Rendering: entries ---------- */

    // "PARAM name: text" arrives as "name: text", name is shown as code.
    function paramText(tag) {
        return tag.kind === "PARAM" ? tag.text.replace(/^([A-Za-z_]\w*):\s*/, "`$1` — ") : tag.text;
    }

    function renderTags(tags) {
        const fields = tags
            .filter((t) => (TAGS[t.kind] || {}).kind === "field")
            .sort((a, b) => FIELD_ORDER.indexOf(a.kind) - FIELD_ORDER.indexOf(b.kind));
        const callouts = tags.filter((t) => (TAGS[t.kind] || {}).kind !== "field");

        let html = "";
        if (fields.length) {
            html += `<dl class="fields">` + fields.map((t) =>
                `<dt>${escapeHtml(TAGS[t.kind].label)}</dt><dd>${renderBlocks(paramText(t))}</dd>`
            ).join("") + `</dl>`;
        }
        for (const t of callouts) {
            const info = TAGS[t.kind] || { label: t.kind, tone: "note" };
            html += `<aside class="callout callout-${info.tone}">` +
                `<div class="callout-label">${escapeHtml(info.label)}</div>${renderBlocks(t.text)}</aside>`;
        }
        return html;
    }

    function buildCard(entry) {
        const card = make("article", "entry");
        card.id = entry.id;

        const signature = entry.decl || entry.symbol;
        card.innerHTML = `
            <header class="entry-head">
                <h2 class="entry-name"><a href="#${escapeHtml(entry.id)}"></a></h2>
                <span class="entry-module">${escapeHtml(entry.module)}</span>
            </header>
            <div class="signature">
                <pre><code>${highlightC(formatSignature(signature, entry.symbol), entry.symbol)}</code></pre>
                <button class="copy" type="button" aria-label="Copy signature">Copy</button>
            </div>
            <div class="entry-body"></div>
        `;

        // Body is kept as HTML, so search marks can be reset by re-assigning it.
        entry.bodyHtml =
            (entry.summary
                ? `<p class="summary">${renderInline(unwrap(entry.summary))}</p>`
                : `<p class="summary missing">No summary.</p>`) +
            (entry.description ? `<div class="description">${renderBlocks(entry.description)}</div>` : "") +
            renderTags(entry.tags);

        entry.card = card;
        entry.nameEl = card.querySelector(".entry-name a");
        entry.bodyEl = card.querySelector(".entry-body");
        entry.bodyEl.innerHTML = entry.bodyHtml;
        entry.marked = false;

        card.querySelector(".copy").addEventListener("click", (ev) => copyText(signature, ev.currentTarget));
    }

    function buildNav() {
        const frag = document.createDocumentFragment();
        for (const mod of state.modules) {
            const group = make("details", "nav-group");
            group.open = true;
            group.innerHTML = `
                <summary>
                    <span class="nav-group-title">${escapeHtml(mod.name)}</span>
                    <span class="nav-group-count">${mod.entries.length}</span>
                </summary>
                <ul class="nav-list"></ul>
            `;
            const list = group.querySelector(".nav-list");
            for (const entry of mod.entries) {
                const item = make("li");
                const link = make("a");
                link.href = `#${entry.id}`;
                link.textContent = entry.name;
                link.title = entry.symbol;
                item.append(link);
                list.append(item);
                entry.navItem = item;
                entry.navLink = link;
            }
            mod.navGroup = group;
            mod.navCount = group.querySelector(".nav-group-count");
            mod.heading = make("h2", "module-heading", escapeHtml(mod.name));
            frag.append(group);
        }
        dom.nav.replaceChildren(frag);
    }


    /* ---------- Search ---------- */

    function tokenize(query) {
        return query.toLowerCase().split(/\s+/).filter(Boolean);
    }

    // Every token must match somewhere; matches in the name weigh the most.
    function score(entry, tokens) {
        const h = entry.haystack;
        let total = 0;
        for (const t of tokens) {
            if (h.symbol === t || h.name === t)                    total += 100;
            else if (h.symbol.startsWith(t) || h.name.startsWith(t)) total += 60;
            else if (h.symbol.includes(t))                         total += 40;
            else if (h.decl.includes(t))                           total += 15;
            else if (h.summary.includes(t))                        total += 10;
            else if (h.rest.includes(t))                           total += 5;
            else return 0;
        }
        return total;
    }

    function applyFilter() {
        const tokens = state.tokens;
        const searching = tokens.length > 0;

        state.visible = searching
            ? state.entries
                .map((e) => ({ e, s: score(e, tokens) }))
                .filter((r) => r.s > 0)
                .sort((a, b) => b.s - a.s || a.e.index - b.e.index)
                .map((r) => r.e)
            : state.entries;

        const visibleSet = new Set(state.visible);

        // Main list: grouped by module when browsing, ranked flat list when searching.
        const frag = document.createDocumentFragment();
        if (searching) {
            frag.append(...state.visible.map((e) => e.card));
        } else {
            for (const mod of state.modules) frag.append(mod.heading, ...mod.entries.map((e) => e.card));
        }
        dom.entries.replaceChildren(frag);

        for (const e of state.visible) {
            e.nameEl.innerHTML = highlight(e.symbol, tokens);
            if (e.marked) e.bodyEl.innerHTML = e.bodyHtml;
            if (searching) markTokens(e.bodyEl, tokens);
            e.marked = searching;
        }

        // Sidebar mirrors the results.
        for (const mod of state.modules) {
            let shown = 0;
            for (const e of mod.entries) {
                const isShown = visibleSet.has(e);
                e.navItem.hidden = !isShown;
                if (isShown) shown++;
            }
            mod.navGroup.hidden = shown === 0;
            mod.navCount.textContent = shown;
        }

        const total = state.entries.length;
        dom.count.textContent = searching
            ? `${state.visible.length} of ${total} symbols`
            : `${total} symbols`;

        dom.empty.hidden = state.visible.length > 0;
        if (state.visible.length === 0) {
            dom.empty.innerHTML = `No symbols match <strong>${escapeHtml(dom.search.value.trim())}</strong>.`;
        }

        dom.clear.hidden = dom.search.value === "";
        observeVisibleCards();
    }

    function setQuery(query, { updateInput = true } = {}) {
        if (updateInput) dom.search.value = query;
        state.tokens = tokenize(query);
        applyFilter();

        const url = new URL(location.href);
        if (query.trim()) url.searchParams.set("q", query.trim());
        else url.searchParams.delete("q");
        history.replaceState(null, "", url);
    }


    /* ---------- Navigation ---------- */

    function goToHash() {
        const id = decodeURIComponent(location.hash.slice(1));
        if (!id) {
            window.scrollTo({ top: 0 });
            return;
        }

        const entry = state.byId.get(id);
        if (!entry) return;

        // The target may be filtered out by the current search.
        if (!entry.card.isConnected) setQuery("");

        entry.card.scrollIntoView({ block: "start" });
        entry.card.classList.remove("flash");
        void entry.card.offsetWidth; // Restart the animation.
        entry.card.classList.add("flash");
        setActive(entry);
    }

    function setActive(entry) {
        if (state.active === entry) return;
        if (state.active) state.active.navLink.classList.remove("active");
        state.active = entry;
        if (!entry) return;

        entry.navLink.classList.add("active");

        // Keep the active link in view inside the sidebar without scrolling the page.
        const nav = dom.nav;
        const link = entry.navLink;
        const top = link.offsetTop - nav.offsetTop;
        if (top < nav.scrollTop + 40 || top > nav.scrollTop + nav.clientHeight - 60) {
            nav.scrollTop = top - nav.clientHeight / 3;
        }
    }

    // Highlights in the sidebar whichever card is at the top of the viewport.
    let observer = null;
    function observeVisibleCards() {
        if (!("IntersectionObserver" in window)) return;
        if (observer) observer.disconnect();

        observer = new IntersectionObserver((records) => {
            const hit = records
                .filter((r) => r.isIntersecting)
                .sort((a, b) => a.boundingClientRect.top - b.boundingClientRect.top)[0];
            if (hit) setActive(state.byId.get(hit.target.id));
        }, { rootMargin: "-70px 0px -65% 0px" });

        for (const e of state.visible) observer.observe(e.card);
    }


    /* ---------- Clipboard ---------- */

    function copyText(text, button) {
        const done = () => {
            button.textContent = "Copied";
            button.classList.add("done");
            setTimeout(() => {
                button.textContent = "Copy";
                button.classList.remove("done");
            }, 1200);
        };

        if (navigator.clipboard && window.isSecureContext) {
            navigator.clipboard.writeText(text).then(done, () => fallbackCopy(text) && done());
        } else if (fallbackCopy(text)) {
            done();
        }
    }

    function fallbackCopy(text) {
        const area = document.createElement("textarea");
        area.value = text;
        area.setAttribute("readonly", "");
        area.style.position = "fixed";
        area.style.opacity = "0";
        document.body.append(area);
        area.select();
        let ok = false;
        try { ok = document.execCommand("copy"); } catch (_) { ok = false; }
        area.remove();
        return ok;
    }


    /* ---------- Events ---------- */

    function bindEvents() {
        dom.search.addEventListener("input", () => setQuery(dom.search.value, { updateInput: false }));

        dom.search.addEventListener("keydown", (ev) => {
            if (ev.key === "Escape") {
                if (dom.search.value) setQuery("");
                else dom.search.blur();
            } else if (ev.key === "Enter" && state.visible.length) {
                const first = state.visible[0];
                if (location.hash === `#${first.id}`) goToHash();
                else location.hash = first.id;
            }
        });

        dom.clear.addEventListener("click", () => {
            setQuery("");
            dom.search.focus();
        });

        document.addEventListener("keydown", (ev) => {
            const slash = ev.key === "/" && !isTypingTarget(ev.target);
            const ctrlK = (ev.ctrlKey || ev.metaKey) && ev.key.toLowerCase() === "k";
            if (slash || ctrlK) {
                ev.preventDefault();
                dom.search.focus();
                dom.search.select();
            }
        });

        // Clicking a link to the current hash does not fire "hashchange"; handle it anyway.
        document.addEventListener("click", (ev) => {
            const link = ev.target instanceof Element && ev.target.closest('a[href^="#"]');
            if (link && link.getAttribute("href") === location.hash && location.hash) {
                ev.preventDefault();
                goToHash();
            }
        });

        window.addEventListener("hashchange", goToHash);
    }


    /* ---------- Startup ---------- */

    function showError(error) {
        const fromFile = location.protocol === "file:";
        dom.status.className = "status error";
        dom.status.innerHTML = `
            <p><strong>Could not load ${DATA_URL}.</strong></p>
            <p>${escapeHtml(error.message || String(error))}</p>
            ${fromFile
                ? `<p>Browsers block loading files from <code>file://</code> pages. Serve the folder instead:</p>
                   <p><code>python3 -m http.server -d doc 8000</code> and open <code>http://localhost:8000</code></p>`
                : `<p>Generate it with <code>./nob doc</code> and reload the page.</p>`}
        `;
        dom.count.textContent = "";
    }

    async function main() {
        bindEvents();
        try {
            const response = await fetch(DATA_URL, { cache: "no-cache" });
            if (!response.ok) throw new Error(`Server responded with ${response.status} ${response.statusText}.`);
            loadEntries(await response.json());
        } catch (error) {
            showError(error);
            return;
        }

        state.entries.forEach(buildCard);
        buildNav();
        dom.status.hidden = true;

        const initialQuery = new URL(location.href).searchParams.get("q") || "";
        setQuery(initialQuery);
        if (location.hash) goToHash();
    }

    main();
})();
